command:
// ==========================================
// LUNAS WIRKUNG: KLUGE FRAGE (NURTI)
//
// - mehrere Targets möglich
// - Zielkategorie: Erwachte
// - nicht auf den Wirkenden
// - Reichweite: 8 Schritt
// - Bonus: mindestens +1, kaufmännisch QS/2
// - Bonus auf alle Geistesfertigkeiten
// - Dauer: QS Minuten
// - gültige Ziele Erfolg, ungültige Misserfolg
// - gespeicherte Ziele ohne neues GM-Target
// - Effektanlage über Block 6
// - Wirkungsende über Block 7
// - eine öffentliche Karte + „Effekt anwenden“
// ==========================================

(async function () {
const macroUuid = this?.uuid || null;

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt = !globalThis.DSK?.Effekt?.Anwenden ||
    !globalThis.DSK?.EffektEnde?.Register || !globalThis.DSK?.QS?.Ermitteln ||
    !globalThis.DSK?.Token?.Finde || !globalThis.DSK?.Target?.Merken ||
    !globalThis.DSK?.Target?.Finden || !globalThis.DSK?.Target?.Actor ||
    !globalThis.DSK?.Wesen?.match || !globalThis.DSK?.Geometrie?.Distanz ||
    !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
    !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
    !globalThis.DSK?.GabenUI?.GMMakroButton ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);
    if (!fwMacro?.execute) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;
if (!DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.Target?.Merken || !DSK_FW?.Target?.Finden ||
    !DSK_FW?.Target?.Actor || !DSK_FW?.Wesen?.match ||
    !DSK_FW?.Geometrie?.Distanz || !DSK_FW?.GMAnfrage?.Speichern ||
    !DSK_FW?.GMAnfrage?.Finden || !DSK_FW?.GMAnfrage?.Lesen ||
    !DSK_FW?.GMAnfrage?.Loeschen || !DSK_FW?.GabenUI?.GMMakroButton ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
    !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!");

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Kluge Frage", vollerName = "Kluge Frage (Nurti)", ahne = "Nurti";
const flagKey = "pendingKlugeFrageNurti", endeKey = "nurtiKlugeFrage", reichweite = 8;
const endeText = "Die durch das Nurtikind verliehene Einsicht verblasst.";

const fertigkeiten = [
    "Gassenkunde", "Geisterkunde", "Geographie", "Geschichten",
    "Menschenkunde", "Orientierung", "Pflanzenkunde",
    "Sinnesschärfe", "Tierkunde", "Zahlenkunde"
];

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
};

const istErwacht = actor =>
    DSK_FW.Wesen.match(actor, ["erwacht", "erwachter", "erwachte"]);

const ladeZiel = async daten => {
    if (!daten) return { token: null, actor: null };
    const token = await DSK_FW.Target.Finden(daten);
    return { token, actor: token?.actor || await DSK_FW.Target.Actor(daten) };
};

const beschreibungFuer = bonus =>
    `Eine geschickt gestellte Frage des Nurtikindes lässt Erinnerungen und Zusammenhänge klarer hervortreten.` +
    `<br><br><b>Bonus:</b> +${bonus} FW auf alle Geistesfertigkeiten` +
    `<br><b>Berechnung:</b> kaufmännisch gerundet QS/2, mindestens +1` +
    `<br><b>Zielkategorie:</b> Erwachte` +
    `<br><b>Reichweite:</b> ${reichweite} Schritt`;

// +++ 4 - EFFEKT ÜBER BLOCK 6 ++++++++++++++++++++++++++++++++

const wendeEffektAn = async ({ casterActor, targetActor, qs, bonus }) => {
    if (!casterActor || !targetActor || !istErwacht(targetActor)) return false;

    const alteEffekte = targetActor.effects.filter(effect =>
        (effect.name || effect.label || "") === vollerName &&
        effect.getFlag("dsk", "casterUuid") === casterActor.uuid
    );

    if (alteEffekte.length) {
        await targetActor.deleteEmbeddedDocuments(
            "ActiveEffect",
            alteEffekte.map(effect => effect.id)
        );
    }

    const changes = fertigkeiten.map(fertigkeit => ({
        key: "system.skillModifiers.FW",
        mode: 0,
        value: `${fertigkeit} ${bonus}`,
        priority: 20
    }));

    const effekt = await DSK_FW.Effekt.Anwenden({
        name: vollerName, ahne,
        beschreibung:
            `Erhält durch eine kluge Frage des Nurtikindes ` +
            `<b>+${bonus} FW auf alle Geistesfertigkeiten</b>.`,
        gabeZiel: "erwachte", qs, ziel: targetActor,
        changes,
        duration: {
            seconds: qs * 60,
            startTime: game.time.worldTime
        },
        showIcon: 1,
        flags: { dsk: {
            isKlugeFrage: true, casterUuid: casterActor.uuid,
            qs, bonus, fertigkeiten,
            wirkungsende: {
                sfName: endeKey, basisEffektName: vollerName,
                beschreibungFuerEnde: endeText
            }
        }}
    });

    if (!effekt) return false;

    const endeDaten = effekt.getFlag("dsk", "wirkungsende");
    const changesKorrekt = fertigkeiten.every(fertigkeit =>
        (effekt.changes || []).some(change =>
            change.key === "system.skillModifiers.FW" &&
            Number(change.mode) === 0 &&
            change.value === `${fertigkeit} ${bonus}`
        )
    );

    return (
        (effekt.name || effekt.label || "") === vollerName &&
        effekt.getFlag("dsk", "isKlugeFrage") === true &&
        effekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
        Number(effekt.getFlag("dsk", "qs")) === qs &&
        Number(effekt.getFlag("dsk", "bonus")) === bonus &&
        endeDaten?.sfName === endeKey &&
        endeDaten?.basisEffektName === vollerName &&
        endeDaten?.beschreibungFuerEnde === endeText &&
        changesKorrekt
    );
};

// +++ 5 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++

const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!game.user.isGM || !casterActor || !daten) return false;
    if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) return false;

    if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
        ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
        return false;
    }

    const casterToken = DSK_FW.Token.Finde(
        casterActor,
        daten.casterTokenId,
        daten.casterTokenUuid
    );

    if (!casterToken) {
        ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`);
        return false;
    }

    const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
    const bonus = Math.max(1, Math.round(qs / 2));
    const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
    const erfolge = [], misserfolge = foundry.utils.deepClone(daten.misserfolge || []);

    for (const zielDaten of daten.ziele || []) {
        const { actor: targetActor } = await ladeZiel(zielDaten);
        const targetName = zielDaten.name || targetActor?.name || "Unbekanntes Ziel";

        if (!targetActor || !istErwacht(targetActor)) {
            misserfolge.push({ name: targetName });
            continue;
        }

        try {
            const erfolgreich = await wendeEffektAn({
                casterActor, targetActor, qs, bonus
            });

            if (erfolgreich) {
                erfolge.push({
                    name: targetName,
                    rolle: "Unterstütztes Ziel"
                });
            } else {
                misserfolge.push({ name: targetName });
            }
        } catch (error) {
            console.error("Kluge Frage: Effektanlage fehlgeschlagen.", {
                targetActor,
                error
            });

            misserfolge.push({ name: targetName });
        }
    }

    const erfolgreich = erfolge.length > 0;

    await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
        messageId: daten.messageId,
        gabenName: vollerName,
        ahne,
        beschreibung: daten.beschreibung,
        wirkender: casterName,
        ziele: erfolge,
        misserfolge,
        dauerText: `${qs} Minuten`,
        erfolgreich
    });

    if (erfolgreich) {
        ui.notifications.info(
            `Luna sagt 🌙: Kluge Frage wurde auf ${erfolge.length} Ziel(e) angewendet.`
        );
    } else {
        ui.notifications.error(
            "Luna sagt 🌙: Kluge Frage konnte auf kein Ziel angewendet werden!"
        );
    }

    return true;
};

// +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++

if (game.user.isGM) {
    const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

    if (anfragen.length) {
        for (const anfrageActor of anfragen) {
            const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
            if (!daten) continue;

            if (await verarbeiteAnfrage(anfrageActor, daten)) {
                await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
            }
        }

        return;
    }
}

// +++ 7 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++++++

let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables.map(token => token.actor)
            .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
        game.actors.find(actor =>
            actor.getFlag("world", "letzteGabenQS") !== undefined
        ) || null;
}

if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");
if (!game.user.isGM && !casterActor.isOwner) {
    return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
}

const casterToken = DSK_FW.Token.Finde(casterActor);
if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Kein Token des Wirkenden gefunden!");

const casterName = DSK_FW.ResolveTokenName(casterActor);
const qs = DSK_FW.QS.Ermitteln({
    actor: casterActor,
    gabenName,
    suchbegriffe: ["Kluge Frage Probe", "Kluge Frage"],
    testDataObj: typeof testData !== "undefined" ? testData : null,
    fallback: 0,
    protokollieren: true
});

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne,
        beschreibung: "Die kluge Frage konnte keine hilfreiche Einsicht vermitteln.",
        wirkender: casterName, ziele: [],
        misserfolge: [{ name: casterName }],
        dauerText: "0 Minuten",
        gmBereich: false, angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 8 - TARGETS PRÜFEN ++++++++++++++++++++++++++++++++++++++

const targets = Array.from(game.user.targets || []);

if (!targets.length) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.warn("Luna sagt 🌙: Bitte wähle mindestens ein Ziel per Target aus!");
}

const ziele = [], misserfolge = [];

for (const targetToken of targets) {
    const targetActor = targetToken?.actor;
    const targetName = targetToken?.name || targetActor?.name || "Unbekanntes Ziel";

    const gueltig = Boolean(
        targetActor &&
        targetActor.uuid !== casterActor.uuid &&
        targetActor.id !== casterActor.id &&
        istErwacht(targetActor) &&
        DSK_FW.Geometrie.Distanz(casterToken, targetToken) <= reichweite
    );

    if (!gueltig) {
        misserfolge.push({ name: targetName });
        continue;
    }

    const zielDaten = DSK_FW.Target.Merken(targetToken);
    if (zielDaten) ziele.push(zielDaten);
    else misserfolge.push({ name: targetName });
}

const bonus = Math.max(1, Math.round(qs / 2));
const beschreibung = beschreibungFuer(bonus);
const dauerText = `${qs} Minuten`;

if (!ziele.length) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung,
        wirkender: casterName, ziele: [], misserfolge,
        dauerText, gmBereich: false,
        angewendet: true, erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await ChatMessage.create({
        speaker: { alias: "System" },
        whisper: [game.user.id],
        content:
            `${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}` +
            `<div class="dskbox2" style="margin-top:10px;text-align:center;">` +
            `<p><b>Kontrolliere deine Target-Auswahl.</b></p>` +
            `<p>Wirke die Gabe erneut, wenn es der GM erlaubt; ansonsten ist dies ein Fehlschlag.</p>` +
            `</div>`
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 9 - GEMEINSAME KARTE + GM-ANFRAGE +++++++++++++++++++++++

const gmLink = DSK_FW.GabenUI.GMMakroButton(
    macroUuid,
    "Effekt anwenden",
    "Das Makro muss durch die Spielleitung ausgeführt werden."
);

const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
    gabenName: vollerName, ahne, beschreibung,
    wirkender: casterName,
    ziele: ziele.map(ziel => ({
        name: ziel.name,
        rolle: "Unterstütztes Ziel"
    })),
    misserfolge,
    dauerText,
    gmLink,
    gmBereich: !game.user.isGM,
    anfragenderUserId: game.user.id
});

if (!nachricht) {
    await raeumeQSAuf(casterActor);
    return ui.notifications.error(
        "Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!"
    );
}

const anfrageDaten = {
    casterUuid: casterActor.uuid,
    casterName,
    casterTokenId: casterToken.id,
    casterTokenUuid:
        casterToken.document?.uuid ||
        casterToken.uuid ||
        null,
    qs,
    ziele,
    misserfolge,
    beschreibung,
    sceneId: canvas.scene?.id || null,
    messageId: nachricht.id,
    macroUuid,
    erstellt: Date.now()
};

// +++ 10 - DIREKT ODER GM-ANFRAGE +++++++++++++++++++++++++++++

if (game.user.isGM) {
    await verarbeiteAnfrage(casterActor, anfrageDaten);
    await raeumeQSAuf(casterActor);
    return;
}

await DSK_FW.GMAnfrage.Speichern(
    casterActor,
    flagKey,
    anfrageDaten
);

await raeumeQSAuf(casterActor);

ui.notifications.info(
    "Luna sagt 🌙: Kluge Frage wurde bei der Spielleitung beantragt."
);

}).call(this);
